sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var user = current.getValue('employee');
    var leaveType = current.getValue('leave_type');
    var daysTaken = parseInt(current.getValue('number_of_leave_days'), 10);

    // Query the Leave Balance table
    var grBalance = new GlideRecord('x_2250616_leave_0_employee_leave_balance'); 
    grBalance.addQuery('employee', user);
    grBalance.query();

    if (grBalance.next()) {
        var currentBalance = 0;

        // Match the dropdown to the balance column and deduct
        if (leaveType == 'sick') {
            currentBalance = parseInt(grBalance.getValue('sick_balance'), 10);
            grBalance.setValue('sick_balance', currentBalance - daysTaken);
        } else if (leaveType == 'casual') {
            currentBalance = parseInt(grBalance.getValue('casual_balance'), 10);
            grBalance.setValue('casual_balance', currentBalance - daysTaken);
        } else if (leaveType == 'annual') {
            currentBalance = parseInt(grBalance.getValue('annual_balance'), 10);
            grBalance.setValue('annual_balance', currentBalance - daysTaken);
        } else if (leaveType == 'emergency') {
            currentBalance = parseInt(grBalance.getValue('emergency_balance'), 10);
            grBalance.setValue('emergency_balance', currentBalance - daysTaken);
        } else if (leaveType == 'maternity') {
            currentBalance = parseInt(grBalance.getValue('maternity_balance'), 10);
            grBalance.setValue('maternity_balance', currentBalance - daysTaken);
        } else if (leaveType == 'paternity') {
            currentBalance = parseInt(grBalance.getValue('paternity_balance'), 10);
            grBalance.setValue('paternity_balance', currentBalance - daysTaken);
        }

        // Save the updated balance
        grBalance.update();
    }

})(current, previous);
